package com.paybridge.core.model;
import java.util.Map;
import java.util.Objects;
public record PaymentRequest(Money amount, String merchantReference, String description, PaymentMethod paymentMethod, IdempotencyKey idempotencyKey, Map<String, String> metadata, Customer customer) { public PaymentRequest { Objects.requireNonNull(amount); if (merchantReference == null || merchantReference.isBlank()) throw new IllegalArgumentException("merchantReference is required"); Objects.requireNonNull(idempotencyKey); metadata = metadata == null ? Map.of() : Map.copyOf(metadata); } public PaymentRequest(Money amount,String merchantReference,String description,PaymentMethod paymentMethod,IdempotencyKey idempotencyKey,Map<String,String> metadata){this(amount,merchantReference,description,paymentMethod,idempotencyKey,metadata,null);} }
